INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 20, 'theory', 'Quiz: backups');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 20, 0, 'Which of these is actually a backup?', '["A two-disk RAID 1 mirror", "An LVM snapshot in the same volume group", "A nightly copy on another server that has already been restored in a test", "A database replica on a neighbouring host"]', 2, 'RAID survives a dead disk, a snapshot dies with its volume group, and a replica repeats an accidental delete too. A backup lives apart from the source, and its restore has been verified.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 20, 1, 'A full copy was made on Sunday, incrementals on Monday through Saturday. On Thursday morning the disk is lost. What is needed to restore to Wednesday?', '["Sunday''s full and the Monday, Tuesday, and Wednesday increments", "Only Wednesday''s copy", "Sunday''s full and Wednesday''s copy", "Every copy of the week, including future ones"]', 0, 'Each increment records the changes since the previous copy, so the whole chain from the last full is needed. A differential copy on Wednesday would have cut the chain to two pieces.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 20, 2, 'The command rsync -a /srv/www /backup/ was run and /srv/www contains index.html. Where will the file end up?', '["/backup/index.html", "/srv/www/backup/index.html", "The command fails without a trailing slash", "/backup/www/index.html"]', 3, 'A source without a slash is copied together with its directory under its own name. With /srv/www/ the file would land directly in /backup.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 20, 3, 'What does --keep-daily 7 mean in restic forget?', '["Every snapshot of the last 7 calendar days", "The newest snapshot in each of the 7 most recent days that have snapshots", "The seven newest snapshots", "Delete every snapshot older than 7 days"]', 1, 'Only days that contain snapshots are counted; empty days are skipped. A snapshot that fits any other rule stays as well.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 20, 4, 'An LVM snapshot made for a backup reached 100 percent before the copy finished. What happens?', '["The origin volume stops until you extend the snapshot", "The snapshot''s old blocks are silently overwritten with new ones", "The snapshot becomes invalid and the copy has to be redone", "The snapshot automatically turns into a full copy of the volume"]', 2, 'The origin volume keeps working, but a snapshot with no room for changed blocks loses consistency and is marked invalid (flag I in lvs). Size it in advance.');
